import{_ as t,c as o,b as l,o as r}from"./app-DKvarYBr.js";const a={};function n(i,e){return r(),o("div",null,e[0]||(e[0]=[l('<p><a href="https://apps.shopify.com/delivery-slot-management" target="_blank" rel="noopener noreferrer">Delivery Slot Management app</a> is a simplified solution to offer scheduled deliveries on Shopify store products.</p><p>The app allows the merchants to add delivery method to the app, create slots for the customers for on-time deliveries and fixed-day deliveries.</p><p>Thus, let customers select a slot when they wish to get the item delivered.</p><p>Now, the <a href="https://webkul.com/blog/delivery-slot-management-for-shopify/" target="_blank" rel="noopener noreferrer">Delivery Slot Management app</a> is integrated with the very popular <strong><a href="https://marketplace-doc.webkul.com/classic/Introduction/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace app</a></strong> for Shopify.</p><p>Enabling this feature app, the merchant can allow sellers to add delivery method and create slots for the customers.</p><p><strong>NOTE</strong>:- The app is compatible with the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-split-cart/" target="_blank" rel="noopener noreferrer">Split Cart feature app</a> in case you want customers to choose cart-wise delivery slot.<br> Also, the app is compatible with <a href="https://webkul.com/blog/shopify-multivendor-marketplace-store-pickup/" target="_blank" rel="noopener noreferrer">Store Pickup</a> &amp; <a href="https://webkul.com/blog/custom-options-multi-vendor-marketplace-for-shopify/" target="_blank" rel="noopener noreferrer">Custom Option</a> feature apps.</p><h3 id="features" tabindex="-1"><a class="header-anchor" href="#features"><span>Features</span></a></h3><ul><li>Sellers can add their own delivery methods and create slots for the customers.</li><li>There will be two delivery options for the sellers: On-time delivery &amp; Fixed-day delivery to create slots.</li><li>Sellers can cancel or reschedule deliveries to your customers.</li><li>Moreover, the sellers can allow customers to reschedule deliveries.</li><li>Have the best option to offer scheduled deliveries on products.</li><li>Also, the sellers can close deliveries on products for some specific days.</li><li>Additionally, create custom fields to get required information from customers.</li><li>Sellers can offer fixed day delivery irrespective of time.</li><li>Also, offer on-time delivery for the customers.</li><li>Sellers can also add customer information to products.</li><li>Moreover, you can assign delivery method to sellers via the Delivery Slot Management App.</li></ul><h3 id="how-to-enable-this-feature-app" tabindex="-1"><a class="header-anchor" href="#how-to-enable-this-feature-app"><span>How To Enable This Feature App?</span></a></h3><p>To get this feature app firstly, you need to install the Delivery Slot Management App on your Shopify store.</p><p>Once done, visit the Feature App section and install the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Feature-Apps-Admin-1200x556.png" alt="Delivery Slot Management"></p><h3 id="configuration" tabindex="-1"><a class="header-anchor" href="#configuration"><span>Configuration</span></a></h3><h4 id="shopify-admin-panel" tabindex="-1"><a class="header-anchor" href="#shopify-admin-panel"><span><strong>Shopify Admin Panel</strong></span></a></h4><p>Now, coming to the Delivery Slot Management App on Shopify admin, you need to visit the Configuration menu and enable the option.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-6-1200x506.png" alt="Delivery Slot Management- configure"></p><p>In this configuration, you will have a configuration &quot;<strong>Include Vendor Delivery Method</strong>&quot;.</p><p>Enabling this tab, both admin&#39;s and vendor&#39;s delivery method will be shown to the customers.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Shopify-1200x549.png" alt="Delivery Slot Management"></p><p>Moreover, you can choose if you want to show the admin&#39;s or the vendor&#39;s delivery methods on product page.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Shopify-1-1200x499.png" alt="Delivery Slot Management"></p><h4 id="assign-delivery-method-to-vendor" tabindex="-1"><a class="header-anchor" href="#assign-delivery-method-to-vendor"><span><strong>Assign Delivery Method To Vendor</strong></span></a></h4><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Shopify-2-1200x549.png" alt="Delivery Slot Management"></p><h4 id="multi-vendor-admin-panel" tabindex="-1"><a class="header-anchor" href="#multi-vendor-admin-panel"><span><strong>Multi-vendor Admin Panel</strong></span></a></h4><p>As soon as you enable the feature app, you will have a new sub-menu added to the <strong>Configuration</strong> menu in the app.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Dashboard-Admin-1200x556.png" alt="Delivery Slot Management"></p><p>Now, you need to enable this configuration to allow sellers to add delivery methods and create slots.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/DSM-Configuration-Admin-1200x556.png" alt="Delivery Slot Management"></p><h2 id="sync-seller" tabindex="-1"><a class="header-anchor" href="#sync-seller"><span>Sync Seller</span></a></h2><p>You can sync the sellers into the app to allow previously added sellers to create delivery methods and add delivery slots to their products.</p><p>For that, visit the Multi-vendor admin panel&gt;&gt;Configuration&gt;&gt;Delivery Slot Management Configuration&gt;&gt;Click <strong>Sync Seller</strong> button.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/Screenshot-20-1200x508.png" alt="Delivery Slot Management"></p><p>Thus, the sellers are synced successfully as shown in the screenshot:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/" alt="Delivery Slot Management"></p><p>Let&#39;s check the configuration on seller end.</p><h3 id="seller-panel" tabindex="-1"><a class="header-anchor" href="#seller-panel"><span>Seller Panel</span></a></h3><p>The sellers will add the delivery methods and create slots from their respective seller panels. For this, the seller needs to visit <strong>Configuration</strong>&gt;&gt;Delivery Slot Management menu.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Dashboard-Seller-•-Multivendor-MarketPlace-1-1200x505.png" alt="Delivery Slot Management-Seller end"></p><h2 id="how-to-add-delivery-methods" tabindex="-1"><a class="header-anchor" href="#how-to-add-delivery-methods"><span>How to Add Delivery Methods?</span></a></h2><p>Clicking the <strong>Add Delivery Method</strong> button, the seller can add a new delivery method. The seller can delete or edit any existing delivery methods as well.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Delivery-SLOT-Configuration-Seller-•-Multivendor-MarketPlace-1200x556.png" alt="Delivery Slot Management"></p><p>The seller will enter the delivery method details and assign delivery slots to the method added.</p><p>Moreover, allow customers to reschedule deliveries and reschedule deliveries after fulfillment.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Delivery-SLOT-Configuration-Seller-•-Multivendor-MarketPlace-1-1200x556.png" alt="Delivery Slot Management"></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-7-1200x441.png" alt="Delivery Slot Management"></p><h2 id="how-to-add-delivery-slots" tabindex="-1"><a class="header-anchor" href="#how-to-add-delivery-slots"><span>How To Add Delivery Slots?</span></a></h2><p>From the Delivery Slot section, the seller can add delivery slots for the customers.</p><p>The seller can allow customers to choose either a fixed date or a fixed date &amp; time for the order delivery.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Delivery-SLOT-Configuration-Seller-•-Multivendor-MarketPlace-2-1200x556.png" alt="Delivery Slot Management"></p><p>While adding a slot, the needs to enter the delivery information such as title of the slot, delivery type: single or multi-user delivery.</p><p><strong>Single User Delivery:</strong> Select this delivery type if you want to allow only one customer to book a slot at a time.</p><p><strong>Multi User Delivery:</strong> Select this delivery type if you want to offer the same time/date slot to multiple customers.</p><p>Thus, You can allow more than one Customer to book a single slot at a time.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Delivery-SLOT-Configuration-Seller-•-Multivendor-MarketPlace-3-1200x556.png" alt="Delivery Slot Management"></p><p>Also, from the <strong>Availability</strong> section, the sellers can configure either Fixed Day Delivery or On-time Delivery options for the customers.</p><h3 id="on-time-delivery" tabindex="-1"><a class="header-anchor" href="#on-time-delivery"><span>On-time Delivery</span></a></h3><p>On-time Delivery:- The seller needs to configure this delivery option if they want to allow customers to choose a preferred date &amp; time to get the item delivered to the destination.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-8-1200x558.png" alt="Delivery Slot Management"></p><p>Also, the seller will enable the weekdays to let customers choose a date for the order delivery.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-9-1200x550.png" alt="Delivery Slot Management"></p><p>Thus, the customer will get the option to choose a date &amp; time for the order deliveries.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Noodles_Home_Delivery_–_sunil_shop12_Chicago_-1-1200x627.png" alt="Noodles_Home_Delivery_–sunil_shop12_Chicago-1"></p><h3 id="fixed-day-delivery" tabindex="-1"><a class="header-anchor" href="#fixed-day-delivery"><span>Fixed-day Delivery</span></a></h3><p>Fixed-day Delivery:- The seller needs to configure this delivery option if they want to allow customers</p><p>To choose a preferred date (irrespective of time) to get the item delivered to the destination.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-10-1200x554.png" alt="Delivery Slot Management"></p><p>Thus, the customer will get the option to choose a date for the order deliveries.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Noodles_Home_Delivery_–_sunil_shop12_Chicago_-2-1200x627.png" alt="Noodles_Home_Delivery_–sunil_shop12_Chicago-2"></p><p><strong>Overwrite Specific days:-</strong> Moreover, the seller can configure this option if they want to close deliveries on some specific days.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-11-1-1200x551.png" alt="Delivery Slot Management"></p><p><strong>Custom Information</strong>:- Show additional information related to your products.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-12-1200x548.png" alt="Delivery Slot Management"></p><p><strong>Custom Field:-</strong> Also, the seller can add custom fields in case you want to add additional information from the customers at the time of placing an order.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Screenshot-13-1200x552.png" alt="Delivery Slot Management"></p><h3 id="customer-end" tabindex="-1"><a class="header-anchor" href="#customer-end"><span>Customer End</span></a></h3><p>Now, to show the delivery widget on the seller&#39;s products, you need to add the codes from the app.</p><h3 id="delivery-widget-on-product-page" tabindex="-1"><a class="header-anchor" href="#delivery-widget-on-product-page"><span>Delivery Widget on Product Page</span></a></h3><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Screenshot16.png" alt="Screenshot16"></p><p>After selecting a delivery method, the customer will get the option to choose a date &amp; time slot for the order delivery.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Sushi_Seafood_Deliveries_–_sunil_shop12_Chicago_-1200x627.png" alt="Sushi_Seafood_Deliveries_–sunil_shop12_Chicago"></p><h2 id="customer-my-account-section" tabindex="-1"><a class="header-anchor" href="#customer-my-account-section"><span>Customer “My Account” Section</span></a></h2><p>Customers can view the delivery details from their account.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Order_1075_–_sunil_shop12_Chicago_-1200x627.png" alt="Order_1075_–sunil_shop12_Chicago"></p><p>Additionally, the customer can request the admin to reschedule the deliveries.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/07/Delivery_Information_–_sunil_shop12_Chicago_-1200x788.png" alt="reschedule"></p><h3 id="delivery-widget-on-cart-page" tabindex="-1"><a class="header-anchor" href="#delivery-widget-on-cart-page"><span>Delivery Widget On Cart Page</span></a></h3><p>You can show seller delivery methods on the cart page of your store. For that, you need to <strong>enable the Split Cart feature app</strong> in the Multi-vendor Marketplace app.</p><p><strong><a href="https://webkul.com/blog/shopify-multivendor-marketplace-split-cart/" target="_blank" rel="noopener noreferrer">Know more about the split cart feature app</a></strong>.</p><p>Now, visit Multi-vendor admin panel&gt;&gt; <strong>Configuration</strong>&gt;&gt;Split Cart Configuration&gt;&gt;Enable Allow Delivery Slot tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/Screenshot-21-4-1200x550.png" alt="Delivery Slot Management"></p><p>Delivery slot</p><p>Visibility of Seller Delivery Method on Cart Page:-</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/05/Your-Shopping-Cart-–-delivery-management-slot-2-1200x556.png" alt="Delivery Slot Management"></p><p>cart page</p><h2 id="deliveries" tabindex="-1"><a class="header-anchor" href="#deliveries"><span>Deliveries</span></a></h2><p>From this section, the seller will have the list of all the order deliveries requested by the customers. Moreover, the seller can edit the delivery and approve &amp; cancel it.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/04/Delivery-SLOT-Configuration-Seller-•-Multivendor-MarketPlace-4-1200x556.png" alt="Delivery Slot Management"></p><p>So, that’s all about the Delivery Slot Management app for the seller.</p><h3 id="demo" tabindex="-1"><a class="header-anchor" href="#demo"><span>Demo</span></a></h3><p>Please check the <strong>Demo</strong> here: <a href="https://delivery-slot-management-demo.myshopify.com/pages/demo" target="_blank" rel="noopener noreferrer">https://delivery-slot-management-demo.myshopify.com/pages/demo</a></p>',100)]))}const p=t(a,[["render",n]]),d=JSON.parse('{"path":"/classic/Featured-App/Marketplace%20Product%20Add-Ons/DELIVERY%20SLOT%20MANAGEMENT.html","title":"DELIVERY SLOT MANAGEMENT","lang":"en-US","frontmatter":{"title":"DELIVERY SLOT MANAGEMENT","description":"DELIVERY SLOT MANAGEMENT","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Features","slug":"features","link":"#features","children":[]},{"level":3,"title":"How To Enable This Feature App?","slug":"how-to-enable-this-feature-app","link":"#how-to-enable-this-feature-app","children":[]},{"level":3,"title":"Configuration","slug":"configuration","link":"#configuration","children":[]},{"level":2,"title":"Sync Seller","slug":"sync-seller","link":"#sync-seller","children":[{"level":3,"title":"Seller Panel","slug":"seller-panel","link":"#seller-panel","children":[]}]},{"level":2,"title":"How to Add Delivery Methods?","slug":"how-to-add-delivery-methods","link":"#how-to-add-delivery-methods","children":[]},{"level":2,"title":"How To Add Delivery Slots?","slug":"how-to-add-delivery-slots","link":"#how-to-add-delivery-slots","children":[{"level":3,"title":"On-time Delivery","slug":"on-time-delivery","link":"#on-time-delivery","children":[]},{"level":3,"title":"Fixed-day Delivery","slug":"fixed-day-delivery","link":"#fixed-day-delivery","children":[]},{"level":3,"title":"Customer End","slug":"customer-end","link":"#customer-end","children":[]},{"level":3,"title":"Delivery Widget on Product Page","slug":"delivery-widget-on-product-page","link":"#delivery-widget-on-product-page","children":[]}]},{"level":2,"title":"Customer “My Account” Section","slug":"customer-my-account-section","link":"#customer-my-account-section","children":[{"level":3,"title":"Delivery Widget On Cart Page","slug":"delivery-widget-on-cart-page","link":"#delivery-widget-on-cart-page","children":[]}]},{"level":2,"title":"Deliveries","slug":"deliveries","link":"#deliveries","children":[{"level":3,"title":"Demo","slug":"demo","link":"#demo","children":[]}]}],"git":{"updatedTime":1757583088000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":1,"url":"https://github.com/pratik"}],"changelog":[{"hash":"bbe1b03e5e919255cadeb8590203b7f1b2e7378e","time":1757583088000,"email":"pratik@webkul.com","author":"pratik","message":"add some new file"}]},"filePathRelative":"classic/Featured-App/Marketplace Product Add-Ons/DELIVERY SLOT MANAGEMENT.md"}');export{p as comp,d as data};
